C[x:=t]=\begin{cases}
lfp(R,\vec y,\varphi,\vec u'),&x\in rng(\vec y),\\
lfp(R,\vec y,\varphi[x:=t],\vec u'),&x\notin rng(\vec y)\land rng(\vec y)\cap FV_{\mathsf T}(t)=\varnothing,\\
lfp(R,\vec z,SubVec_{LFP}(\varphi,\vec y,\vec z)[x:=t],\vec u'),&\text{否则},
\end{cases}

g[\vec x:=\vec d](y)=
\begin{cases}
\vec d(i),&\text{若 }y=\vec x(i)\ (i<n),\\
g(y),&\text{否则};
\end{cases}

G[R:=S](T)=
\begin{cases}
S,&T=R,\\
G(T),&T\ne R,
\end{cases}
\qquad T\in\mathsf{RVar}_m,\ m\in\mathbb N.

\mathsf{PosMon}_{LFP}
=
\{(M,g,G,R,\vec x,\varphi):
M=(D,I_{\mathcal F},I_{\mathcal R})\in\mathsf{Struct}_{\Sigma}
\land\exists n\in\mathbb N\ (R\in\mathsf{RVar}_n\land \vec x:n\to\mathsf{Var}\ \text{单射}
\land g:\mathsf{Var}\to D
\land G\in\prod_{m\in\mathbb N}\mathcal P(D^m)^{\mathsf{RVar}_m}
\land\varphi\in\mathsf{Fm}_{LFP}^{\Sigma}
\land
\operatorname{Pos}_{R}^{+}(\varphi)
\land
\operatorname{Mon}_{D,n}(F_{\varphi,\vec x}^{M,g,G,R}))\}.
